#include <stdio.h>
int compute(void){int a[5]={ 10,4,7,5,6 }; int n=5;for(int i=0;i<n;i++){for(int j=0;j<n-1;j++){if(a[j]>a[j+1]){int t=a[j];a[j]=a[j+1];a[j+1]=t;}}}return a[0]+a[4];}
int main(void){printf("%d\n", compute());return 0;}

